-- Cofrin: use numeric(14,2) for persisted amounts. Application mocks use number,
-- while split calculations round to cents at the domain boundary.
create extension if not exists "pgcrypto";
create type transaction_type as enum ('INCOME','EXPENSE','TRANSFER');
create type transaction_status as enum ('PAID','RECEIVED','PENDING','OVERDUE');
create table profiles (id uuid primary key references auth.users(id), full_name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), name text not null, type text not null, initial_balance numeric(14,2) not null default 0, current_balance numeric(14,2) not null default 0, institution text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table categories (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), name text not null, kind transaction_type, color text, icon text, created_at timestamptz not null default now());
create table credit_cards (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), name text not null, brand text, last_four_digits text not null, credit_limit numeric(14,2) not null, closing_day int not null, due_day int not null, color text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), type transaction_type not null, nature text not null, description text not null, amount numeric(14,2) not null check(amount>0), transaction_date date not null, category_id uuid references categories(id), account_id uuid references accounts(id), credit_card_id uuid references credit_cards(id), payment_method text, status transaction_status not null, recurrence_type text not null default 'SINGLE', installment_number int, installment_count int, parent_transaction_id uuid references transactions(id), notes text, group_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table piggy_banks (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), name text not null, description text, target_amount numeric(14,2) not null, monthly_contribution numeric(14,2), deadline date, icon text, status text not null default 'ACTIVE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table piggy_bank_movements (id uuid primary key default gen_random_uuid(), piggy_bank_id uuid not null references piggy_banks(id), user_id uuid not null references profiles(id), type text not null check(type in ('DEPOSIT','WITHDRAWAL')), amount numeric(14,2) not null check(amount>0), movement_date date not null, description text, created_at timestamptz not null default now());
create table groups (id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(id), name text not null, description text, type text not null, target_amount numeric(14,2), event_date date, image_url text, status text not null default 'ACTIVE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table group_members (id uuid primary key default gen_random_uuid(), group_id uuid not null references groups(id) on delete cascade, user_id uuid not null references profiles(id), role text not null default 'MEMBER', expected_contribution numeric(14,2), status text not null default 'ACTIVE', joined_at timestamptz not null default now(), unique(group_id,user_id));
create table group_contributions (id uuid primary key default gen_random_uuid(), group_id uuid not null references groups(id), member_id uuid not null references group_members(id), amount numeric(14,2) not null check(amount>0), contribution_date date not null, created_at timestamptz not null default now());
create table group_expenses (id uuid primary key default gen_random_uuid(), group_id uuid not null references groups(id), paid_by_member_id uuid references group_members(id), description text not null, amount numeric(14,2) not null check(amount>0), payment_source text not null check(payment_source in ('GROUP_FUND','MEMBER')), expense_date date not null, created_at timestamptz not null default now());
create table budgets (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), category_id uuid not null references categories(id), limit_amount numeric(14,2) not null, period text not null default 'MONTHLY', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table credit_card_invoices (id uuid primary key default gen_random_uuid(), credit_card_id uuid not null references credit_cards(id), reference_month int not null check(reference_month between 1 and 12), reference_year int not null, total_amount numeric(14,2) not null default 0, due_date date not null, status text not null default 'OPEN', created_at timestamptz not null default now(), unique(credit_card_id,reference_month,reference_year));
create table installments (id uuid primary key default gen_random_uuid(), transaction_id uuid not null references transactions(id), installment_number int not null, installment_count int not null, due_date date not null, amount numeric(14,2) not null, created_at timestamptz not null default now());
create table group_expense_splits (id uuid primary key default gen_random_uuid(), expense_id uuid not null references group_expenses(id) on delete cascade, user_id uuid not null references profiles(id), amount numeric(14,2) not null, percentage numeric(5,2), shares int, status text not null default 'PENDING', created_at timestamptz not null default now());
create table settlements (id uuid primary key default gen_random_uuid(), group_id uuid not null references groups(id), from_user_id uuid not null references profiles(id), to_user_id uuid not null references profiles(id), amount numeric(14,2) not null check(amount>0), status text not null default 'SUGGESTED', created_at timestamptz not null default now(), settled_at timestamptz);
create table notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), type text not null, title text not null, message text not null, read boolean not null default false, action_url text, created_at timestamptz not null default now());
alter table profiles enable row level security; alter table accounts enable row level security; alter table categories enable row level security; alter table transactions enable row level security; alter table piggy_banks enable row level security; alter table piggy_bank_movements enable row level security; alter table credit_cards enable row level security; alter table budgets enable row level security;
alter table groups enable row level security; alter table group_members enable row level security; alter table group_contributions enable row level security; alter table group_expenses enable row level security; alter table group_expense_splits enable row level security; alter table settlements enable row level security; alter table notifications enable row level security;
create policy "users own profile" on profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "users own accounts" on accounts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users own transactions" on transactions for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users own piggies" on piggy_banks for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "members view groups" on groups for select using (owner_id=auth.uid() or exists(select 1 from group_members where group_members.group_id=groups.id and group_members.user_id=auth.uid() and group_members.status='ACTIVE'));
create policy "members view expenses" on group_expenses for select using (exists(select 1 from group_members where group_members.group_id=group_expenses.group_id and group_members.user_id=auth.uid() and group_members.status='ACTIVE'));
create policy "users own notifications" on notifications for all using (user_id=auth.uid()) with check (user_id=auth.uid());
